-- ============================================================================
-- ml.churn_features — feature store model for churn_model
-- ----------------------------------------------------------------------------
-- Generated by: data-engineer (governed agent run run-9c1e4f2b7a0d)
-- Plan (allowed through the gateway):
--   transform raw.churn_survey + events.raw_clickstream  -> allow (allow-engineering)
--   write     ml.churn_features                         -> allow (allow-engineering)
-- Lineage (per DataHub): events.raw_clickstream -> ml.churn_features -> churn_model
-- ============================================================================

-- 1) Survey signals, joined to the clickstream by account
with survey as (
    select
        respondent_id as account_id,
        nps,
        usage_frequency,
        lower(sentiment) as sentiment
    from `raw.churn_survey`
    where partition_date = @run_date
),

clickstream as (
    select
        user_id as account_id,
        date_diff(current_date(), date(max(ts)), day) as days_since_last_login,
        approx_quantiles(request_duration_ms, 100)[offset(99)] as p99_latency_30d
    from `events.raw_clickstream`
    where ts >= date_add(@run_date, interval -30 day)
    group by user_id
),

-- 2) Features stay a single row per account so downstream joins are simple
final as (
    select
        coalesce(s.account_id, c.account_id)            as account_id,
        s.nps                                          as nps,
        s.usage_frequency                              as usage_frequency,
        coalesce(c.days_since_last_login, 30)          as days_since_last_login,
        coalesce(c.p99_latency_30d, 0.0)               as p99_latency_30d,
        @run_date                                      as feature_ts
    from survey s
    full outer join clickstream c using (account_id)
)

select * from final
